22	/// Capacity of the default in-memory session provider when the caller does not supply
23	/// a custom [`SessionProvider`] via
24	/// [`AgentCoreServerBuilder::session_provider`].
25	const DEFAULT_MAX_SESSIONS: usize = 4096;
