27	// ── AppState ──────────────────────────────────────────────────────────────────
28	
29	/// Inner shared state; allocated once per [`AgentCoreServer`] and reference-counted.
30	///
31	/// This is the shape a handler reaches for via `State<AppState<Ctx>>` (or, for `/ping`,
32	/// via the [`FromRef`] substate below). `pub(crate)` (rather than private) so
33	/// [`crate::invoke`]'s `/invocations` handler — in its own module, per the crate's
34	/// one-file-per-route layout — can read every field without re-deriving the state
35	/// layout; neither the type nor its fields are re-exported from the crate root, so
36	/// this stays out of the public API.
37	pub(crate) struct AppStateInner<Ctx> {
38	    /// The single agent this AgentCore container serves.
39	    pub(crate) agent: Arc<dyn Agent<Ctx>>,
40	    /// Execution backend driving each invocation.
41	    pub(crate) runner: Arc<dyn Runner<Ctx>>,
42	    /// Session store consulted for requests carrying the AgentCore session header.
43	    pub(crate) sessions: Arc<dyn SessionProvider>,
44	    /// Per-request context builder.
45	    pub(crate) context: Arc<dyn ContextProvider<Ctx>>,
46	    /// Default run configuration applied to every invocation.
47	    pub(crate) run_config: RunConfig,
48	    /// Shared health-check state backing `GET /ping`.
49	    ping: Arc<PingState>,
50	}
51	
52	/// Cheaply-cloneable axum extraction state.
53	///
54	/// All handler tasks share a single [`AppStateInner<Ctx>`] through this wrapper. Cloning
55	/// is an [`Arc`] increment, not a deep copy. `pub(crate)` for the same reason as
56	/// [`AppStateInner`] — [`crate::invoke::invocations`] takes `State<AppState<Ctx>>`
57	/// directly rather than a bespoke extractor.
58	pub(crate) struct AppState<Ctx> {
59	    inner: Arc<AppStateInner<Ctx>>,
60	}
61	
62	impl<Ctx> Clone for AppState<Ctx> {
63	    fn clone(&self) -> Self {
64	        Self {
65	            inner: Arc::clone(&self.inner),
66	        }
67	    }
68	}
69	
70	impl<Ctx> std::ops::Deref for AppState<Ctx> {
71	    type Target = AppStateInner<Ctx>;
72	
73	    fn deref(&self) -> &Self::Target {
74	        &self.inner
75	    }
76	}
