89	/// Builder for [`AgentCoreServer`].
90	///
91	/// Obtain via [`AgentCoreServer::builder`]. All setters consume and return `Self` for
92	/// chaining. Call [`build`](AgentCoreServerBuilder::build) once an agent and a context
93	/// provider have been supplied.
94	pub struct AgentCoreServerBuilder<Ctx> {
95	    agent: Option<Arc<dyn Agent<Ctx>>>,
96	    runner: Option<Arc<dyn Runner<Ctx>>>,
97	    sessions: Option<Arc<dyn SessionProvider>>,
98	    context: Option<Arc<dyn ContextProvider<Ctx>>>,
99	    run_config: RunConfig,
100	}
