102	impl<Ctx: Send + Sync + 'static> AgentCoreServerBuilder<Ctx> {
103	    fn new() -> Self {
104	        Self {
105	            agent: None,
106	            runner: None,
107	            sessions: None,
108	            context: None,
109	            run_config: RunConfig::default(),
110	        }
111	    }
112	
113	    /// Set the single [`Agent`] this AgentCore container serves.
114	    ///
115	    /// Required: [`build`](AgentCoreServerBuilder::build) returns
116	    /// [`AgentCoreError::Internal`] if this is never called.
117	    pub fn agent(mut self, agent: Arc<dyn Agent<Ctx>>) -> Self {
118	        self.agent = Some(agent);
119	        self
120	    }
121	
122	    /// Override the execution backend. Defaults to [`TokioRunner`].
123	    pub fn runner(mut self, runner: Arc<dyn Runner<Ctx>>) -> Self {
124	        self.runner = Some(runner);
125	        self
126	    }
127	
128	    /// Override the session provider. Defaults to an [`InMemorySessionProvider`] bounded
129	    /// to a fixed capacity.
130	    pub fn session_provider(mut self, provider: Arc<dyn SessionProvider>) -> Self {
131	        self.sessions = Some(provider);
132	        self
133	    }
134	
135	    /// Set the context provider.
136	    ///
137	    /// Required unless [`with_default_context`](AgentCoreServerBuilder::with_default_context)
138	    /// is called (only available when `Ctx: Default`). [`build`] returns
139	    /// [`AgentCoreError::Internal`] if neither is invoked.
140	    ///
141	    /// [`build`]: AgentCoreServerBuilder::build
142	    pub fn context_provider(mut self, provider: Arc<dyn ContextProvider<Ctx>>) -> Self {
143	        self.context = Some(provider);
144	        self
145	    }
146	
147	    /// Override the run configuration applied to every invocation. Defaults to
148	    /// [`RunConfig::default`].
149	    pub fn run_config(mut self, config: RunConfig) -> Self {
150	        self.run_config = config;
151	        self
152	    }
153	
154	    /// Build an [`AgentCoreServer`].
155	    ///
156	    /// # Errors
157	    ///
158	    /// - [`AgentCoreError::Internal`] — no agent was registered; call
159	    ///   [`agent`](AgentCoreServerBuilder::agent).
160	    /// - [`AgentCoreError::Internal`] — no context provider was supplied (either via
161	    ///   [`context_provider`](AgentCoreServerBuilder::context_provider) or
162	    ///   [`with_default_context`](AgentCoreServerBuilder::with_default_context)).
163	    pub fn build(self) -> Result<AgentCoreServer<Ctx>, AgentCoreError> {
164	        let agent = self.agent.ok_or_else(|| {
165	            AgentCoreError::Internal(
166	                "no agent set; call `.agent(...)` before `.build()`".to_owned(),
167	            )
168	        })?;
169	
170	        let context = self.context.ok_or_else(|| {
171	            AgentCoreError::Internal(
172	                "no context provider set; call `.context_provider(…)` or \
173	                 `.with_default_context()` (requires Ctx: Default)"
174	                    .to_owned(),
175	            )
176	        })?;
177	
178	        let runner: Arc<dyn Runner<Ctx>> = self.runner.unwrap_or_else(|| Arc::new(TokioRunner));
179	
180	        let sessions: Arc<dyn SessionProvider> = self
181	            .sessions
182	            .unwrap_or_else(|| Arc::new(InMemorySessionProvider::new(DEFAULT_MAX_SESSIONS)));
183	
184	        Ok(AgentCoreServer {
185	            state: AppState {
186	                inner: Arc::new(AppStateInner {
187	                    agent,
188	                    runner,
189	                    sessions,
190	                    context,
191	                    run_config: self.run_config,
192	                    ping: Arc::new(PingState::default()),
193	                }),
194	            },
195	        })
196	    }
197	}
