213	/// Self-hosted HTTP server that mounts a single [`Agent`] on an axum router satisfying
214	/// the AWS Bedrock AgentCore HTTP-protocol container contract.
215	///
216	/// # Quick start
217	///
218	/// ```ignore
219	/// # use std::sync::Arc;
220	/// # use paigasus_helikon_runtime_agentcore::AgentCoreServer;
221	/// # async fn run() -> Result<(), Box<dyn std::error::Error>> {
222	/// let server = AgentCoreServer::<()>::builder()
223	///     .with_default_context()
224	///     .agent(Arc::new(my_agent))
225	///     .build()?;
226	///
227	/// server.serve().await?;
228	/// # Ok(())
229	/// # }
230	/// ```
231	pub struct AgentCoreServer<Ctx> {
232	    state: AppState<Ctx>,
233	}
234	
235	impl<Ctx: Send + Sync + 'static> AgentCoreServer<Ctx> {
236	    /// Return a new builder.
237	    pub fn builder() -> AgentCoreServerBuilder<Ctx> {
238	        AgentCoreServerBuilder::new()
239	    }
240	
241	    /// Build the axum [`Router`].
242	    ///
243	    /// Pure: spawns nothing. Mounts `GET /ping` (see [`PingState`]; always resolves,
244	    /// independent of the agent/runner/session state) and `POST /invocations` (accepts
245	    /// [`InvocationRequest`](crate::InvocationRequest)'s three body shapes and serves
246	    /// both the buffered-JSON and Server-Sent-Events response modes — see the crate's
247	    /// top-level docs for the full request/response contract). Suitable for embedding
248	    /// into a larger router or for testing with `tower`'s `ServiceExt::oneshot`.
249	    pub fn router(&self) -> Router {
250	        Router::new()
251	            .route("/ping", get(ping::ping))
252	            .route("/invocations", post(invoke::invocations::<Ctx>))
253	            .with_state(self.state.clone())
254	    }
255	
256	    /// Return a handle to the shared health-check state backing `GET /ping`.
257	    ///
258	    /// Call [`PingState::set_busy`] on the returned handle to flag long-running
259	    /// asynchronous work (e.g. performed by a tool) so the *next* health check reflects
260	    /// it immediately.
261	    pub fn ping_state(&self) -> Arc<PingState> {
262	        Arc::clone(&self.state.ping)
263	    }
264	
265	    /// Return a clone of the configured [`Agent`] handle.
266	    ///
267	    /// `pub(crate)`: an internal wiring seam for [`crate::mcp`]'s MCP-protocol mode
268	    /// (feature `mcp`), which needs the shared agent to build its own
269	    /// `McpAgentServer`. Not public API — callers configure the agent via
270	    /// [`AgentCoreServerBuilder::agent`] and never need it handed back.
271	    #[cfg_attr(not(feature = "mcp"), allow(dead_code))]
272	    pub(crate) fn agent(&self) -> Arc<dyn Agent<Ctx>> {
273	        Arc::clone(&self.state.agent)
274	    }
275	
276	    /// Bind `0.0.0.0:8080` — the fixed port AgentCore's HTTP-protocol contract expects —
277	    /// and serve until the process is terminated.
278	    ///
279	    /// Logs `"ready in {ms}ms"` immediately after the listener is bound: AgentCore's
280	    /// cold-start acceptance criterion is measured against this app-side signal (the
281	    /// platform's own microVM provisioning latency is outside this crate's control).
282	    ///
283	    /// # Errors
284	    ///
285	    /// Returns [`AgentCoreError::Internal`] if binding the listener or the serve loop
286	    /// itself fails.
287	    pub async fn serve(self) -> Result<(), AgentCoreError> {
288	        let start = std::time::Instant::now();
289	        let listener = tokio::net::TcpListener::bind("0.0.0.0:8080")
290	            .await
291	            .map_err(|e| AgentCoreError::Internal(format!("failed to bind 0.0.0.0:8080: {e}")))?;
292	        let router = self.router();
293	        let elapsed_ms = start.elapsed().as_millis();
294	        tracing::info!(elapsed_ms = elapsed_ms as u64, "ready in {elapsed_ms}ms");
295	        axum::serve(listener, router)
296	            .await
297	            .map_err(|e| AgentCoreError::Internal(e.to_string()))
298	    }
299	}
